                                }
                            }
                        }
                    }
                }
                return true;
            }
        });

        // Execute
        boolean result = realUnderTest.setPosition(1);

        // Verify
        assertTrue(result);
        verify(mockNodeSet, never()).add(any());
    }

    @Test
    public void testSetPosition_NoNodesInSet() {
        // Setup
        when(mockContext1.nextSet()).thenReturn(true);
        when(mockContext1.nextNode()).thenReturn(false); // No nodes in this set
        when(mockContext2.nextSet()).thenReturn(false);

        UnionContext realUnderTest = spy(new UnionContext(mockParentContext, contexts) {
            private boolean prepared = false;
            @Override
            protected Object getNodeSet() { return mockNodeSet; }
