                        while (ctx.nextSet()) {
                            while (ctx.nextNode()) {
                                NodePointer ptr = ctx.getCurrentNodePointer();
                                if (!pointers.contains(ptr)) {
                                    nodeSet.add(ptr);
                                    pointers.add(ptr);
                                }
                            }
                        }
                    }
                }
                return true;
            }
        });

        // Execute
        boolean result = realUnderTest.setPosition(1);

        // Verify
        assertTrue(result);
        verify(mockNodeSet, never()).add(any());
    }
}
